var i=[{title:`Μηχανική πάνω από το κεφάλι`,text:`Ξεκινήστε από σταθερή όρθια ή καθιστή βάση. Κρατήστε τα πλευρά σας περίπου στοιβαγμένα πάνω από τη λεκάνη, σφίξτε τον κορμό και πιέστε προς τα πάνω κατά μήκος μιας άνετης διαδρομής ώστε τα χέρια σας να τελειώνουν πάνω από το κεφάλι χωρίς μεγάλη κλίση προς τα πίσω. Οι ωμοπλάτες σας περιστρέφονται κανονικά προς τα πάνω καθώς ανεβαίνουν τα χέρια, και το να προσπαθείτε να τις καρφώσετε στη θέση τους καθ’ όλη την άσκηση μπορεί να το εμποδίσει.`},{title:`Κινητικότητα και ατομικές διαφορές`,text:`Το φτάσιμο πάνω από το κεφάλι απαιτεί αρκετή κίνηση του ώμου και συνήθως κάποια βοήθεια από την άνω πλάτη. Η ανατομία του ώμου και οι άνετες γωνίες λαβής διαφέρουν από άτομο σε άτομο. Αν μια πίεση με ευθεία μπάρα είναι άβολη, μια πίεση με αλτήρες σε ουδέτερη λαβή, μια πίεση landmine ή ένα μικρότερο εύρος πάνω από το κεφάλι μπορεί να σας ταιριάζει καλύτερα. Ο έντονος πόνος σημαίνει σταμάτημα, οπότε μην προσπαθήσετε να τον ξεπεράσετε με διάταση.`},{title:`Επιλογές με το σωματικό βάρος`,text:`Μια κάμψη pike βάζει τα ισχία σας ψηλά, έτσι οι ώμοι σας αναλαμβάνουν μεγαλύτερο μέρος του φορτίου. Μια κάμψη pike με υπερυψωμένα πόδια μπορεί να είναι δυσκολότερη και χρειάζεται περισσότερη ισορροπία και χώρο. Για αρχάριους, μια ελαφριά όρθια πίεση με αλτήρες είναι συχνά απλούστερη και ευκολότερη στη ρύθμιση από μια δύσκολη παραλλαγή με το σωματικό βάρος.`},{title:`Συνηθισμένα προβλήματα τεχνικής`,text:`Μια μεγάλη καμπύλωση στη χαμηλή μέση, το να πιέζετε το βάρος πολύ μπροστά σας και το να βιάζεστε σε ασταθείς επαναλήψεις σημαίνουν συνήθως ότι το φορτίο είναι πολύ βαρύ ή ο έλεγχός σας περιορισμένος. Μειώστε το βάρος, εξασκηθείτε στη διαδρομή και κρατήστε τα πόδια σας έξω από μια αυστηρή πίεση. Η πίεση push press είναι ξεχωριστή άσκηση που προσθέτει σκόπιμα ώθηση από τα πόδια.`},{title:`Χρήση του TrainUp`,text:`Το πρόγραμμά σας περιλαμβάνει ασκήσεις πάνω από το κεφάλι μόνο όταν ο εξοπλισμός σας και το ύψος οροφής στο Profile σας αφήνουν αρκετό χώρο. Επίσης ταιριάζει τις ασκήσεις στον συντονισμό σας. Αν ευαίσθητοι ώμοι ή η φόρτιση της σπονδυλικής στήλης κάνουν τις συνηθισμένες πιέσεις πάνω από το κεφάλι κακή επιλογή, προσθέστε έναν περιορισμό για αυτή την περιοχή του σώματος στο Profile και το πρόγραμμα θα επιλέξει λιγότερο απαιτητικές επιλογές.`}];var s=[{label:`Βιβλιοθήκη ασκήσεων του ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: τεχνική προπόνησης με βάρη (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA: ασφάλεια και βασικές αρχές της προπόνησης με αντίσταση`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var l={sections:i,sources:s};export{l as default,i as sections,s as sources};